import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, DoubleSide } from 'three/webgpu';
import { uv, vec2, vec3, float, smoothstep, mix, Fn, uniform, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { DataTexture, RGBAFormat, LinearSRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-pricing-badge';

  const width = 0.92;
  const height = 0.34;
  const radius = height * 0.5;
  const straight = width - height;

  // Spec palette
  const accentV = vec3(1.0, 0.165, 0.220);   // #ff2a38
  const surfaceV = vec3(0.043, 0.043, 0.063); // #0b0b10
  const inkV = vec3(0.086, 0.086, 0.114);     // #16161d

  // Safe default texture until the ceramic grain loads
  const defArr = new Uint8Array([90, 90, 110, 255]);
  const defaultTex = new DataTexture(defArr, 1, 1, RGBAFormat);
  defaultTex.needsUpdate = true;
  const grainTex = uniform(defaultTex);

  // Capsule SDF (horizontal capsule)
  const sdCapsule = Fn(([p, a, b, r]) => {
    const pa = p.sub(a);
    const ba = b.sub(a);
    const h = pa.dot(ba).div(ba.dot(ba)).clamp(0, 1);
    return pa.sub(ba.mul(h)).length().sub(r);
  });

  // Centered UV coords in scene units
  const p = vec2(uv().x.sub(0.5).mul(width), uv().y.sub(0.5).mul(height));
  const aA = vec2(float(straight).mul(-0.5), float(0));
  const aB = vec2(float(straight).mul(0.5), float(0));
  const d = sdCapsule(p, aA, aB, float(radius));

  // Soft capsule mask (anti-aliased)
  const mask = smoothstep(float(0.0045), float(-0.0045), d);

  // Accent edge light: inner rim band + outer halo -> the ONE brightest element
  const innerRim = smoothstep(float(-0.03), float(0.0), d).mul(mask);
  const outerRim = smoothstep(float(0.05), float(0.0), d.max(0.0));
  const edgeGlow = innerRim.add(outerRim.mul(0.8));

  // Ceramic grain modulates the fill subtly
  const grainSample = texture(grainTex, uv()).r;
  const grain = grainSample.mul(0.35);
  const fill = surfaceV.add(inkV.mul(0.5)).mul(float(0.85).add(grain));

  const colorOut = mix(fill, accentV, edgeGlow);
  const alphaOut = mask.add(outerRim.mul(0.5)).clamp(0.0, 1.0);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false
  });
  material.colorNode = colorOut;
  material.alphaNode = alphaOut;

  const geo = new PlaneGeometry(width, height);
  const mesh = new Mesh(geo, material);
  mesh.renderOrder = 6;
  group.add(mesh);

  // Load ceramic grain map
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = LinearSRGBColorSpace;
      grainTex.value = tex;
    });
  }

  // Interactions
  const baseY = config.scenePosition?.y ?? 0.7;
  const baseScale = 1;
  let hoverTween = null;
  let pressTL = null;

  const handlers = {
    hover: (active) => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: active ? baseY + 0.15 : baseY,
        duration: 0.55,
        ease: 'power3.out',
        overwrite: true
      });
    },
    click: () => {
      if (pressTL) pressTL.kill();
      pressTL = gsap.timeline()
        .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' })
        .to(group.scale, { x: baseScale, y: baseScale, z: baseScale, duration: 0.2, ease: 'power3.out' });
      ctx.emit('hub-pricing.select', { from: 'hub-pricing-badge' });
    }
  };
  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTL) pressTL.kill();
    geo.dispose();
    material.dispose();
    defaultTex.dispose();
    if (grainTex.value && grainTex.value !== defaultTex) grainTex.value.dispose?.();
  };

  return group;
}
